function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H - 50 - Math.sin(t) * 100, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 50 - Math.sin(t) * 100 + 20);
  ctx.lineTo(W/2, H - 50 - Math.sin(t) * 100 + 20 + Math.sin(t) * 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 50 - Math.sin(t) * 100 + 20 + Math.sin(t) * 100);
  ctx.lineTo(W/2 - 20, H - 50 - Math.sin(t) * 100 + 20 + Math.sin(t) * 100 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 50 - Math.sin(t) * 100 + 20 + Math.sin(t) * 100);
  ctx.lineTo(W/2 + 20, H - 50 - Math.sin(t) * 100 + 20 + Math.sin(t) * 100 + 20);
  ctx.stroke();
  ctx.restore();
}
